+  startOffset: number,
+  barH: number,
+  segBytes: number,
+  rowStep: number,
+  channels: number
+): number {
+  let greenPixels = 0;
+  let rowStartOffset = startOffset;
+  for (let py = 0; py < barH; py++) {
+    const endOffset = rowStartOffset + segBytes;
