+      const g = arr[offset + 1];
+      if (g > arr[offset] + 10 && g > arr[offset + 2] + 10) {
+        greenPixels++;
+      }
+    }
+    rowStartOffset += rowStep;
+  }
+  return greenPixels;
+}
